-- PREPARED ONLY. Adds first-party aggregates and protected admin functions.
begin;
create or replace function public.study_public_stats() returns jsonb language sql stable security definer set search_path='' as $$
select jsonb_build_object('registered_users',(select count(*) from public.study_profiles),'weekly_active_users',(select count(distinct user_id) from public.study_events where created_at>now()-interval '7 days'),'monthly_active_users',(select count(distinct user_id) from public.study_events where created_at>now()-interval '30 days'),'questions_answered',(select count(*) from public.study_attempts),'correct_answers',(select count(*) from public.study_attempts where is_correct),'cards_reviewed',(select count(*) from public.study_events where event_type='card_review'),'study_hours',(select coalesce(round(sum(least(300,greatest(0,coalesce((details->>'seconds')::numeric,0))))/3600,2),0) from public.study_events where event_type='active_time'),'modules_available',(select count(*) from public.study_modules)) $$;
create or replace function public.study_admin_dashboard() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare result jsonb;begin
 if not public.study_is_admin() then raise exception 'Admin access required';end if;
 result=jsonb_build_object('metrics',public.study_public_stats(),
 'reports',(select coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) from(select id,item_id,category,details,status,created_at from public.study_reports order by created_at desc limit 300)r),
 'users',(select coalesce(jsonb_agg(to_jsonb(u)),'[]'::jsonb) from(select p.user_id as id,p.name,p.branch,p.admission_year,p.onboarding_done,p.created_at,(select max(e.created_at) from public.study_events e where e.user_id=p.user_id) as last_active,(select count(*) from public.study_attempts a where a.user_id=p.user_id) as questions_answered from public.study_profiles p order by p.created_at desc limit 500)u),
 'pages',(select coalesce(jsonb_agg(to_jsonb(v)),'[]'::jsonb) from(select details->>'path' as page,count(*) as views from public.study_events where event_type='page_view' group by details->>'path' order by views desc limit 50)v),
 'devices',(select coalesce(jsonb_agg(to_jsonb(v)),'[]'::jsonb) from(select coalesce(details->>'device_class','unknown') as device,count(*) as views from public.study_events where event_type='page_view' group by details->>'device_class')v),
 'sources',(select coalesce(jsonb_agg(to_jsonb(v)),'[]'::jsonb) from(select coalesce(details->>'referrer','direct') as source,count(*) as views from public.study_events where event_type='page_view' group by details->>'referrer' order by views desc limit 30)v),
 'funnel',jsonb_build_object('registered',(select count(*) from public.study_profiles),'profile_finished',(select count(*) from public.study_profiles where onboarding_done),'answered_ten',(select count(*) from(select user_id from public.study_attempts group by user_id having count(*)>=10)x),'reviewed_ten_cards',(select count(*) from(select user_id from public.study_events where event_type='card_review' group by user_id having count(*)>=10)x)),
 'retention',(select coalesce(jsonb_agg(to_jsonb(c)),'[]'::jsonb) from(select date_trunc('week',p.created_at)::date as cohort,count(*) as registered,count(*) filter(where exists(select 1 from public.study_events e where e.user_id=p.user_id and e.created_at>=p.created_at+interval '6 days' and e.created_at<p.created_at+interval '9 days')) as returned_day_seven from public.study_profiles p where p.created_at<now()-interval '9 days' group by date_trunc('week',p.created_at)::date order by cohort desc limit 26)c),
 'content',(select coalesce(jsonb_agg(to_jsonb(c)),'[]'::jsonb) from(select m.subject,m.module_id,jsonb_array_length(coalesce(m.payload->'cards','[]'::jsonb)) as cards,jsonb_array_length(coalesce(m.payload->'mcq','[]'::jsonb)) as core_questions,jsonb_array_length(coalesce(m.payload->'bonus','[]'::jsonb)) as bonus_questions,coalesce(m.payload->'verification'->>'status','source_checked') as review_status,(select count(*) from public.study_reports r where r.item_id like '%'||m.module_id||'%' and r.status='open') as open_reports from public.study_modules m order by m.subject,m.module_id)c),
 'system',jsonb_build_object('server_time',now(),'last_event',(select max(created_at) from public.study_events),'locations','Not collected','accuracy','Recomputed server-side from the current content pack','study_time','Estimated from active browser intervals'));
 return result;
end $$;
create function public.study_admin_user(p_user uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$
begin if not public.study_is_admin() then raise exception 'Admin access required';end if;return jsonb_build_object('profile',(select to_jsonb(p) from public.study_profiles p where user_id=p_user),'attempts',(select coalesce(jsonb_agg(to_jsonb(a)),'[]'::jsonb) from(select module_id,question_id,selected,is_correct,elapsed_ms,created_at from public.study_attempts where user_id=p_user order by created_at desc limit 100)a),'events',(select coalesce(jsonb_agg(to_jsonb(e)),'[]'::jsonb) from(select event_type,details,created_at from public.study_events where user_id=p_user order by created_at desc limit 100)e));end $$;
revoke all on function public.study_admin_user(uuid) from public;grant execute on function public.study_admin_user(uuid) to authenticated;
create function public.study_resolve_report(p_id uuid,p_status text) returns void language plpgsql security definer set search_path='' as $$
begin if not public.study_is_admin() then raise exception 'Admin access required';end if;if p_status not in('open','reviewing','resolved','dismissed')then raise exception 'Unknown status';end if;update public.study_reports set status=p_status where id=p_id;end $$;
revoke all on function public.study_resolve_report(uuid,text) from public;grant execute on function public.study_resolve_report(uuid,text) to authenticated;
create function public.study_prune_analytics(p_days integer default 180) returns integer language plpgsql security definer set search_path='' as $$
declare removed integer;begin if not public.study_is_admin() then raise exception 'Admin access required';end if;if p_days<30 or p_days>730 then raise exception 'Retention must be 30 to 730 days';end if;delete from public.study_events where created_at<now()-make_interval(days=>p_days);get diagnostics removed=row_count;return removed;end $$;
revoke all on function public.study_prune_analytics(integer) from public;grant execute on function public.study_prune_analytics(integer) to authenticated;
create function public.study_export_my_data() returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid();begin if uid is null then raise exception 'Sign in required';end if;return jsonb_build_object('exported_at',now(),'profile',(select to_jsonb(p) from public.study_profiles p where user_id=uid),'progress',(select coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) from public.study_progress p where user_id=uid),'attempts',(select coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) from public.study_attempts p where user_id=uid),'reports',(select coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) from public.study_reports p where user_id=uid),'events',(select coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) from public.study_events p where user_id=uid));end $$;
revoke all on function public.study_export_my_data() from public;grant execute on function public.study_export_my_data() to authenticated;
commit;
